where exists (
    select 1 from price_items existing_trade
    where existing_trade.company_id = c.id and existing_trade.category like 'Abbruch %'
  )
  and not exists (
    select 1 from price_items existing
    where existing.company_id = c.id
      and split_part(existing.category, ' – ', 1) = 'Abbruch'
      and lower(btrim(existing.title)) = lower(btrim(p.title))
      and lower(btrim(existing.unit)) = lower(btrim(p.unit))
  );

-- ── Allgemein (13 Katalogzeilen) ──────────────────────────────
insert into price_items (company_id, category, title, unit, unit_price)
select c.id, p.category, p.title, p.unit, p.unit_price
from companies c
cross join (values
  ('Allgemein', 'Stundenlohn Facharbeiter', 'Std', 68.00::numeric),
  ('Allgemein', 'Stundenlohn Geselle', 'Std', 58.00::numeric),
  ('Allgemein', 'Stundenlohn Helfer', 'Std', 42.00::numeric),
  ('Allgemein', 'Anfahrtspauschale', 'Pausch', 35.00::numeric),
  ('Allgemein', 'Fahrtkosten (je km, einfache Strecke)', 'km', 0.40::numeric),
  ('Allgemein', 'Aufpreis Stockwerk ohne Aufzug (2.OG)', 'Pausch', 80.00::numeric),
  ('Allgemein', 'Aufpreis Stockwerk ohne Aufzug (3.OG+)', 'Pausch', 140.00::numeric),
  ('Allgemein', 'Aufpreis Wochenendarbeit', 'Pausch', 150.00::numeric),
  ('Allgemein', 'Schutzmaßnahmen bewohnte Wohnung', 'Pausch', 95.00::numeric),
  ('Allgemein', 'Bauschutt-Container 7m³', 'Stk', 380.00::numeric),
  ('Allgemein', 'Bauschutt-Container 10m³', 'Stk', 480.00::numeric),
  ('Allgemein', 'Aggregat / Stromerzeuger (je Tag)', 'Tag', 110.00::numeric),
  ('Allgemein', 'Kleintransporter (je Tag)', 'Tag', 95.00::numeric)
) as p(category, title, unit, unit_price)
where exists (
    select 1 from price_items existing_trade
    where existing_trade.company_id = c.id and existing_trade.category = 'Allgemein'
  )
  and not exists (
    select 1 from price_items existing
    where existing.company_id = c.id
      and split_part(existing.category, ' – ', 1) = 'Allgemein'
      and lower(btrim(existing.title)) = lower(btrim(p.title))
      and lower(btrim(existing.unit)) = lower(btrim(p.unit))
  );

