) as p(category, title, unit, unit_price)
where exists (
    select 1 from price_items existing_trade
    where existing_trade.company_id = c.id and existing_trade.category like 'Elektro %'
  )
  and not exists (
    select 1 from price_items existing
    where existing.company_id = c.id
      and split_part(existing.category, ' – ', 1) = 'Elektro'
      and lower(btrim(existing.title)) = lower(btrim(p.title))
      and lower(btrim(existing.unit)) = lower(btrim(p.unit))
  );

-- ── Entrümpelung (46 Katalogzeilen) ──────────────────────────────
insert into price_items (company_id, category, title, unit, unit_price)
select c.id, p.category, p.title, p.unit, p.unit_price
from companies c
cross join (values
  ('Entrümpelung – Anfahrt & Organisation', 'Anfahrt pauschal (bis 20 km)', 'Pauschale', 55.00::numeric),
  ('Entrümpelung – Anfahrt & Organisation', 'Besichtigungstermin / Aufnahme vor Ort', 'Stunde', 65.00::numeric),
