  ('Entrümpelung – Räumung', 'Entrümpelung / Räumung pauschal (je m² Wohnfläche, Normalfall)', 'm²', 14.00::numeric),
  ('Entrümpelung – Räumung', 'Entrümpelung stark vermüllt / voll möbliert (je m²)', 'm²', 25.00::numeric),
